"""Heatmap view data: display tones, row summaries, team row, KPIs, cell details."""

from __future__ import annotations

import datetime as dt

from alloq_commons.services.utilization import HEAT_HIGH, HEAT_LOW, HEAT_MID
from alloq_project.services.planning_builders import GERMAN_MONTHS
from alloq_project.states.planning_models import (
    EmployeeBlock,
    HeatAssignment,
    HeatCell,
    HeatDetail,
    HeatKpis,
    HeatRow,
    HeatTeamCell,
    WeekColumn,
)

HEAT_CRITICAL: int = 150
SORT_KEYS: tuple[str, ...] = ("name", "avg", "free")
NO_FREE_WEEK = "—"
NO_ABSENCE = "Keine geplant"


def heat_tone(percent: int, *, is_absent: bool) -> str:
    """Display tone of a utilization: blue up to 100 %, warm when overbooked."""
    if is_absent:
        return "absent"
    if percent <= 0:
        return "zero"
    if percent < HEAT_LOW:
        return "low"
    if percent < HEAT_MID:
        return "mid"
    if percent <= HEAT_HIGH:
        return "high"
    if percent <= HEAT_CRITICAL:
        return "over"
    return "critical"


def de_days(value: float) -> str:
    """Person-days in German notation with at most one decimal (``14,3``)."""
    text = f"{round(value, 1) + 0.0:.1f}".rstrip("0").rstrip(".")
    return text.replace(".", ",")


def _day_count(days: float) -> str:
    return f"{de_days(days)} {'Tag' if days == 1 else 'Tage'}"


def _week_start(week_key: str) -> dt.date:
    year, month, day = (int(part) for part in week_key.split("_"))
    return dt.date(year, month, day)


def week_range(week_key: str) -> str:
    """Monday to Friday of a week, e.g. ``19.–23. Okt 2026``."""
    start = _week_start(week_key)
    end = start + dt.timedelta(days=4)
    end_text = f"{end.day}. {GERMAN_MONTHS[end.month - 1]} {end.year}"
    if start.month == end.month:
        return f"{start.day}.–{end_text}"
    return f"{start.day}. {GERMAN_MONTHS[start.month - 1]} – {end_text}"


def current_index(weeks: list[WeekColumn], current_key: str) -> int:
    """Column of the current week; the first column if it is not shown."""
    return next((i for i, w in enumerate(weeks) if w.key == current_key), 0)


def heat_hint(week_no: int, cell: HeatCell) -> str:
    """Tooltip and screen reader text of one heatmap cell."""
    if cell.is_absent:
        return f"KW {week_no}: abwesend"
    text = (
        f"KW {week_no}: {cell.percent} %, {de_days(cell.booked_days)} von "
        f"{de_days(cell.capacity_days)} PT gebucht"
    )
    if cell.absence_days > 0:
        text += f", {_day_count(cell.absence_days)} abwesend"
    return text


def _decorated(cells: list[HeatCell], weeks: list[WeekColumn]) -> list[HeatCell]:
    return [
        cell.model_copy(
            update={
                "tone": heat_tone(cell.percent, is_absent=cell.is_absent),
                "hint": heat_hint(week.week_no, cell),
            }
        )
        for cell, week in zip(cells, weeks, strict=False)
    ]


def _average(cells: list[HeatCell]) -> int:
    present = [c.percent for c in cells if not c.is_absent]
    return round(sum(present) / len(present)) if present else 0


def _is_free(cell: HeatCell) -> bool:
    return not cell.is_absent and cell.capacity_days > 0 and cell.percent < HEAT_LOW


def _free_index(cells: list[HeatCell], start: int) -> int | None:
    return next((i for i in range(start, len(cells)) if _is_free(cells[i])), None)


def _free_label(
    idx: int | None, start: int, weeks: list[WeekColumn]
) -> tuple[str, str]:
    if idx is None:
        return NO_FREE_WEEK, "none"
    if idx == start:
        return "sofort", "now"
    return f"KW {weeks[idx].week_no}", "later"


def build_heat_rows(
    blocks: list[EmployeeBlock],
    weeks: list[WeekColumn],
    current_key: str,
    sort: str = "name",
) -> list[HeatRow]:
    """Heatmap rows with tones, average and first free week, sorted."""
    start = current_index(weeks, current_key)
    keyed: list[tuple[tuple[str, str], int, HeatRow]] = []
    for block in blocks:
        cells = _decorated(block.heat, weeks)
        avg = _average(cells[start:])
        free_idx = _free_index(cells, start)
        free_from, free_state = _free_label(free_idx, start, weeks)
        row = HeatRow(
            id=block.id,
            real_id=block.real_id,
            name=block.name,
            initials=block.initials,
            job_title=block.job_title,
            avg_percent=avg,
            avg_tone=heat_tone(avg, is_absent=False),
            free_from=free_from,
            free_state=free_state,
            cells=cells,
        )
        name_key = (block.last_name.casefold(), block.first_name.casefold())
        rank = len(weeks) + 1 if free_idx is None else free_idx
        keyed.append((name_key, rank, row))
    keyed.sort(key=lambda item: item[0])
    if sort == "avg":
        keyed.sort(key=lambda item: -item[2].avg_percent)
    elif sort == "free":
        keyed.sort(key=lambda item: item[1])
    return [row for _, _, row in keyed]


def build_team_cells(
    blocks: list[EmployeeBlock], weeks: list[WeekColumn]
) -> list[HeatTeamCell]:
    """Capacity-weighted team utilization and free person-days per week."""
    out: list[HeatTeamCell] = []
    for idx, week in enumerate(weeks):
        present = [
            b.heat[idx] for b in blocks if idx < len(b.heat) and not b.heat[idx].is_absent
        ]
        capacity = sum(c.capacity_days for c in present)
        booked = sum(c.booked_days for c in present)
        free = sum(max(0.0, c.capacity_days - c.booked_days) for c in present)
        percent = round(booked / capacity * 100) if capacity > 0 else 0
        out.append(
            HeatTeamCell(
                week_key=week.key,
                percent=percent,
                tone=heat_tone(percent, is_absent=not present),
                has_capacity=capacity > 0,
                free_days=free,
                free_label=de_days(free),
            )
        )
    return out


def _next_absence(
    blocks: list[EmployeeBlock], weeks: list[WeekColumn], start: int
) -> tuple[str, str]:
    for idx in range(start, len(weeks)):
        names = [
            b.name for b in blocks if idx < len(b.heat) and b.heat[idx].is_absent
        ]
        if names:
            return f"KW {weeks[idx].week_no}", ", ".join(names)
    return NO_ABSENCE, ""


def build_kpis(
    blocks: list[EmployeeBlock], weeks: list[WeekColumn], current_key: str
) -> HeatKpis:
    """Headline figures: this week's overbooking and free capacity, outlook."""
    if not weeks:
        return HeatKpis()
    start = current_index(weeks, current_key)
    now = [
        (b, b.heat[start])
        for b in blocks
        if start < len(b.heat) and not b.heat[start].is_absent
    ]
    over = [b.name for b, c in now if c.percent > HEAT_HIGH]
    free = sum(max(0.0, c.capacity_days - c.booked_days) for _, c in now)
    ahead = [c for b in blocks for c in b.heat[start:] if not c.is_absent]
    capacity = sum(c.capacity_days for c in ahead)
    booked = sum(c.booked_days for c in ahead)
    next_absence, absence_names = _next_absence(blocks, weeks, start)
    return HeatKpis(
        week_no=weeks[start].week_no,
        over_count=len(over),
        over_names=", ".join(over),
        free_label=de_days(free),
        free_people=sum(1 for _, c in now if _is_free(c)),
        team_percent=round(booked / capacity * 100) if capacity > 0 else 0,
        next_absence=next_absence,
        next_absence_names=absence_names,
    )


def _summary(cell: HeatCell) -> str:
    if cell.is_absent:
        return "Die ganze Woche abwesend."
    booked, capacity = cell.booked_days, cell.capacity_days
    if booked <= 0:
        text = f"Keine Zuweisung, {de_days(capacity)} PT frei."
    elif booked > capacity:
        text = (
            f"{de_days(booked)} PT gebucht bei {de_days(capacity)} PT Kapazität, "
            f"{de_days(booked - capacity)} PT zu viel."
        )
    else:
        text = (
            f"{de_days(booked)} von {de_days(capacity)} PT gebucht, "
            f"{de_days(capacity - booked)} PT frei."
        )
    if cell.absence_days > 0:
        text += f" {_day_count(cell.absence_days)} abwesend."
    return text


def build_detail(
    block: EmployeeBlock, weeks: list[WeekColumn], week_key: str
) -> HeatDetail | None:
    """Detail of one employee week: utilization, capacity bar, assignments."""
    idx = next((i for i, w in enumerate(weeks) if w.key == week_key), None)
    if idx is None or idx >= len(block.heat):
        return None
    cell = block.heat[idx]
    scale = max(HEAT_HIGH, cell.percent)
    projects = sorted(
        (p for p in block.projects if idx < len(p.cells) and p.cells[idx].value > 0),
        key=lambda p: -p.cells[idx].value,
    )
    return HeatDetail(
        emp_id=block.id,
        name=block.name,
        initials=block.initials,
        week_no=weeks[idx].week_no,
        date_range=week_range(week_key),
        percent=cell.percent,
        tone=heat_tone(cell.percent, is_absent=cell.is_absent),
        is_absent=cell.is_absent,
        summary=_summary(cell),
        capacity_label=f"{de_days(cell.capacity_days)} PT",
        bar_normal=0.0
        if cell.is_absent
        else min(cell.percent, HEAT_HIGH) / scale * 100,
        bar_over=max(0, cell.percent - HEAT_HIGH) / scale * 100,
        assignments=[
            HeatAssignment(
                name=p.name,
                color=p.color,
                days_label=f"{de_days(p.cells[idx].value)} PT",
            )
            for p in projects
        ],
    )

