class PlanningHeatmapState(rx.State, mixin=True):
    """Heatmap-only view state on top of the filtered `employees` pivot.

    A mixin like `PlanningDisplayState`: the vars derive from `PlanningStore`
    vars and the heatmap components read both side by side.
    """

    if TYPE_CHECKING:  # Provided by PlanningStore.
        weeks: list[WeekColumn]
