    heat_selected_emp: rx.Field[str] = rx.field("")
    heat_selected_week: rx.Field[str] = rx.field("")

    @rx.event
    def set_heat_sort(self, value: str) -> None:
        if value in SORT_KEYS:
            self.heat_sort = value

    @rx.event
    def select_heat_cell(self, emp_id: str, week_key: str) -> None:
        """Open the detail panel for a cell; the same cell again closes it."""
        same = self.heat_selected_emp == emp_id and self.heat_selected_week == week_key
        self.heat_selected_emp = "" if same else emp_id
        self.heat_selected_week = "" if same else week_key

    @rx.event
    def close_heat_detail(self) -> None:
        self.heat_selected_emp = ""
        self.heat_selected_week = ""

    @rx.event
    def open_heat_selection_in_grid(self) -> None:
        """Show the selected employee in the editable grid."""
        block = next((e for e in self.employees if e.id == self.heat_selected_emp), None)
        if block is not None:
            self.employee_filter = [str(block.real_id)]
            self.view_mode = GRID_VIEW
        self.close_heat_detail()

    @rx.var(cache=True)
    def heat_rows(self) -> list[HeatRow]:
        return build_heat_rows(
            self.employees, self.weeks, self.current_week_key, self.heat_sort
        )

    @rx.var(cache=True)
