        return build_kpis(self.employees, self.weeks, self.current_week_key)

    @rx.var(cache=True)
    def heat_detail(self) -> HeatDetail:
        block = next((e for e in self.employees if e.id == self.heat_selected_emp), None)
        if block is None:
            return HeatDetail()
        return build_detail(block, self.weeks, self.heat_selected_week) or HeatDetail()

    @rx.var(cache=True)
