        return (
            f"{HEAT_LABEL_PX}px {HEAT_AVG_PX}px {HEAT_FREE_PX}px "
            f"repeat({len(self.weeks)}, minmax({HEAT_WEEK_MIN_PX}px, 1fr))"
        )

    @rx.var(cache=True)
    def heat_table_min_width(self) -> str:
        fixed = HEAT_LABEL_PX + HEAT_AVG_PX + HEAT_FREE_PX
        return f"{fixed + len(self.weeks) * HEAT_WEEK_MIN_PX}px"

