import appkit_mantine as mn

ROW_MIN_HEIGHT = "40px"
HEADER_BG = theme.SURFACE_MUTED
BODY_BG = theme.SURFACE

STICKY_COLUMNS = (
    {"left": "0"},
    {"left": f"{HEAT_LABEL_PX}px"},
    {
        "left": f"{HEAT_LABEL_PX + HEAT_AVG_PX}px",
        "borderRight": f"1px solid {theme.token('border-strong')}",
    },
)


def _sticky(column: int, background: str, **style: str) -> dict:
    return {
        "position": "sticky",
        "zIndex": "3",
        "backgroundColor": background,
        **STICKY_COLUMNS[column],
        **style,
    }


def _heat_row(*children: rx.Component, **props: object) -> rx.Component:
    return mn.box(
        *children,
        style={
            "display": "grid",
            "gridTemplateColumns": PlanningStore.heat_template_columns,
            "minWidth": PlanningStore.heat_table_min_width,
            "borderBottom": f"1px solid {theme.BORDER}",
        },
        **props,
    )


def _week_class(week_key: rx.Var[str], base: str) -> rx.Var[str]:
    return rx.cond(
        week_key == PlanningStore.current_week_key, base + " aq-heat-now", base
    )


def _month_border(week_key: rx.Var[str]) -> rx.Var[str]:
    return rx.cond(
        PlanningStore.month_start_keys.contains(week_key), MONTH_START_BORDER, "none"
    )


# ---------------------------- Header ---------------------------------------


def _month_cell(month: ObjectVar[MonthSpan]) -> rx.Component:
    return mn.box(
        mn.text(month.label, size="xs", fw="700"),
        style={
            "gridColumn": "span " + month.span.to_string(),
            "display": "flex",
            "alignItems": "center",
            "padding": "0 8px",
            "height": "30px",
            "borderLeft": f"1px solid {theme.BORDER}",
        },
    )


def _sort_button(label: str, key: str, column: int, hint: str) -> rx.Component:
    return rx.el.button(
        label,
        rx.icon("arrow-down", size=12, stroke_width=2),
        type="button",
        class_name="aq-heat-th",
        title=hint,
        on_click=PlanningStore.set_heat_sort(key),
        custom_attrs={
            "data-active": rx.cond(PlanningStore.heat_sort == key, "true", "false"),
            "aria-pressed": rx.cond(PlanningStore.heat_sort == key, "true", "false"),
        },
        style=_sticky(column, HEADER_BG, paddingLeft="16px" if column == 0 else "10px"),
    )


def _week_head(week: ObjectVar[WeekColumn]) -> rx.Component:
    is_now = week.key == PlanningStore.current_week_key
    return mn.box(
        mn.text(
            week.week_no.to_string(),
            size="xs",
            fw=rx.cond(is_now, "700", "500"),
            c=rx.cond(is_now, "#FFFFFF", theme.TEXT_MUTED),
            px=6,
            style={
                "borderRadius": "9px",
                "backgroundColor": rx.cond(is_now, theme.ACCENT, "transparent"),
                **theme.NUMERIC,
            },
        ),
        title=rx.cond(is_now, "Aktuelle Woche", ""),
        style={
            "display": "flex",
            "alignItems": "center",
            "justifyContent": "center",
            "height": "30px",
            "borderLeft": _month_border(week.key),
        },
    )


def _header() -> rx.Component:
    return mn.box(
        _heat_row(
            mn.group(
                mn.text("Mitarbeiter", style=CAPS_LABEL),
                mn.text(
                    PlanningStore.heat_rows.length().to_string(),
                    size="xs",
                    c=theme.TEXT_MUTED,
                ),
                gap=6,
                px=16,
                style=_sticky(0, HEADER_BG, gridColumn="span 3", height="30px"),
            ),
            rx.foreach(PlanningStore.month_spans, _month_cell),
        ),
        _heat_row(
            _sort_button("Name", "name", 0, "Nach Nachname sortieren"),
            _sort_button("Ø %", "avg", 1, "Durchschnitt ab dieser Woche"),
            _sort_button(
                "Frei ab", "free", 2, "Erste Woche mit mindestens 30 % freier Kapazität"
            ),
            rx.foreach(PlanningStore.weeks, _week_head),
        ),
        style={
            "position": "sticky",
            "top": "0",
            "zIndex": "30",
            "backgroundColor": HEADER_BG,
        },
    )


# ---------------------------- Body -----------------------------------------


def _heat_cell(row: ObjectVar[HeatRow], cell: ObjectVar[HeatCell]) -> rx.Component:
    selected = (PlanningStore.heat_selected_emp == row.id) & (
        PlanningStore.heat_selected_week == cell.week_key
    )
    return mn.box(
        rx.el.button(
            rx.cond(
                cell.is_absent,
                rx.icon("plane", size=14, stroke_width=1.6),
                cell.percent.to_string(),
            ),
            type="button",
            class_name=tone_class("aq-heat-cell", cell.tone),
            title=cell.hint,
            aria_label=row.name + ", " + cell.hint,
            on_click=PlanningStore.select_heat_cell(row.id, cell.week_key),
            custom_attrs={
                "data-selected": rx.cond(selected, "true", "false"),
                "data-partial": rx.cond(
                    (cell.absence_days > 0) & ~cell.is_absent, "true", "false"
                ),
            },
        ),
        class_name=_week_class(cell.week_key, ""),
        style={
            "display": "flex",
            "alignItems": "center",
            "padding": "3px 2px",
            "borderLeft": _month_border(cell.week_key),
        },
    )


def _label_cell(row: ObjectVar[HeatRow]) -> rx.Component:
    return mn.group(
        mn.avatar(row.initials, size=28, radius="xl", color="blue"),
        mn.stack(
            mn.text(row.name, size="sm", fw="600", truncate="end", lh="1.2"),
            rx.cond(
                row.job_title != "",
                mn.text(
                    row.job_title, size="xs", c=theme.TEXT_MUTED, truncate="end"
                ),
                rx.fragment(),
            ),
            gap=0,
            style={"minWidth": "0"},
        ),
        gap=10,
        wrap="nowrap",
        px=16,
        style=_sticky(0, BODY_BG, minHeight=ROW_MIN_HEIGHT, minWidth="0"),
    )


def _avg_cell(row: ObjectVar[HeatRow]) -> rx.Component:
    return mn.center(
        mn.box(
            row.avg_percent.to_string(),
            class_name=tone_class("aq-heat-pill", row.avg_tone),
        ),
        style=_sticky(1, BODY_BG),
    )


def _free_cell(row: ObjectVar[HeatRow]) -> rx.Component:
    return mn.center(
        mn.text(
            row.free_from,
            size="xs",
            fw=rx.cond(row.free_state == "none", "400", "600"),
            c=rx.match(
                row.free_state,
                ("now", theme.POSITIVE),
                ("none", theme.TEXT_TERTIARY),
                theme.TEXT,
            ),
        ),
        style=_sticky(2, BODY_BG),
    )


def _body_row(row: ObjectVar[HeatRow]) -> rx.Component:
    return _heat_row(
        _label_cell(row),
        _avg_cell(row),
        _free_cell(row),
        rx.foreach(row.cells, lambda cell: _heat_cell(row, cell)),
        class_name="aq-heat-row",
        custom_attrs={
            "data-selected": rx.cond(
                PlanningStore.heat_selected_emp == row.id, "true", "false"
            ),
        },
    )


# ---------------------------- Footer ---------------------------------------


def _footer_label(text: str) -> rx.Component:
    return mn.box(
        mn.text(text, style=CAPS_LABEL),
        px=16,
        style=_sticky(
            0,
            HEADER_BG,
            gridColumn="span 3",
            display="flex",
            alignItems="center",
            minHeight="30px",
        ),
    )


def _team_cell(cell: ObjectVar[HeatTeamCell]) -> rx.Component:
    return mn.box(
        mn.box(
            rx.cond(cell.has_capacity, cell.percent.to_string(), "–"),
            class_name=tone_class("aq-heat-cell aq-heat-static", cell.tone),
        ),
        class_name=_week_class(cell.week_key, ""),
        style={
            "display": "flex",
            "alignItems": "center",
            "padding": "3px 2px",
            "borderLeft": _month_border(cell.week_key),
        },
    )


def _free_days_cell(cell: ObjectVar[HeatTeamCell]) -> rx.Component:
    return mn.center(
        mn.text(
            cell.free_label,
            size="xs",
            fw=rx.cond(cell.free_days >= 5, "700", "400"),
            c=rx.cond(cell.free_days >= 5, theme.POSITIVE, theme.TEXT_MUTED),
            style=theme.NUMERIC,
        ),
        class_name=_week_class(cell.week_key, ""),
        style={"minHeight": "28px", "borderLeft": _month_border(cell.week_key)},
    )


def _footer() -> rx.Component:
    return mn.box(
        _heat_row(
            _footer_label("Team Ø %"),
            rx.foreach(PlanningStore.heat_team, _team_cell),
        ),
        _heat_row(
            _footer_label("PT frei"),
            rx.foreach(PlanningStore.heat_team, _free_days_cell),
        ),
        style={
            "position": "sticky",
            "bottom": "0",
            "zIndex": "20",
            "backgroundColor": HEADER_BG,
            "borderTop": f"1px solid {theme.token('border-strong')}",
            "marginTop": "auto",
        },
    )


# ---------------------------- View -----------------------------------------


def _grid() -> rx.Component:
    return mn.box(
        mn.box(
            _header(),
            rx.foreach(PlanningStore.heat_rows, _body_row),
            _footer(),
            role="grid",
            aria_label="Auslastung je Mitarbeiter und Woche",
            style={
                "display": "flex",
                "flexDirection": "column",
                "minHeight": "100%",
                "minWidth": PlanningStore.heat_table_min_width,
            },
        ),
        id="planning-heatmap-root",
        style={**GRID_WRAPPER_STYLE, "outline": "none"},
    )


def planning_heatmap() -> rx.Component:
    return rx.cond(
        PlanningStore.is_loaded,
        mn.box(
            rx.el.style(HEATMAP_CSS),
            heatmap_summary_bar(),
            _grid(),
            rx.cond(PlanningStore.has_heat_detail, heatmap_detail_panel()),
            style={
                "display": "flex",
                "flexDirection": "column",
                "flex": "1",
                "minHeight": "0",
                "width": "100%",
                "fontVariantNumeric": "tabular-nums",
            },
        ),
        mn.center(
            rx.hstack(
                rx.spinner(size="3"),
                mn.text("Lade Heatmap...", size="sm"),
                align="center",
                spacing="3",
            ),
            py="xl",
        ),
    )

